/** A Turn's size class by estimated tokens; see `notes/buckets.md`. */
export type Bucket = "tiny" | "small" | "medium" | "large" | "huge";

/** Lower bounds inclusive, upper bounds exclusive; `huge` is unbounded above. */
export function bucketOf(tokens: number): Bucket {
	if (tokens < 350) return "tiny";
	if (tokens < 1800) return "small";
	if (tokens < 7000) return "medium";
	if (tokens < 24000) return "large";
	return "huge";
}

