export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

export type Bucket = (typeof BUCKETS)[number];

/** Exclusive upper bound of each bucket but the last, which is unbounded above. */
const BELOW = [350, 1800, 7000, 24000] as const;

/** Lower bounds inclusive, upper bounds exclusive. */
export function bucketOf(tokens: number): Bucket {
	const index = BELOW.findIndex((bound) => tokens < bound);
	return BUCKETS[index === -1 ? BUCKETS.length - 1 : index];
}

