/** Turn size classes by estimated tokens, smallest first; see `notes/buckets.md`. */
export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

export type Bucket = (typeof BUCKETS)[number];

/** Exclusive upper bound of each bucket; `huge` is unbounded above. */
const BELOW: Record<Bucket, number> = {
	tiny: 350,
	small: 1800,
	medium: 7000,
	large: 24000,
	huge: Number.POSITIVE_INFINITY,
};

/**
 * The smallest bucket whose upper bound exceeds `tokens`; lower bounds are inclusive.
 *
 * @throws RangeError when `tokens` is negative, infinite or NaN: no bucket holds it.
 */
export function bucketOf(tokens: number): Bucket {
	if (!Number.isFinite(tokens) || tokens < 0) {
		throw new RangeError(`Turn size must be a finite, non-negative token count: ${tokens}`);
	}
	// Unreachable fallback: every finite size is below `huge`'s infinite bound.
	return BUCKETS.find((bucket) => tokens < BELOW[bucket]) ?? "huge";
}

