import { describe, expect, test } from "bun:test";

import { weighted } from "./budget-table.ts";

describe("weighted", () => {
	test.each([
		[349, 174.5],
		[350, 350],
		[1799, 1799],
		[1800, 2250],
		[6999, 8748.75],
		[7000, 10500],
		[23999, 35998.5],
		[24000, 54000],
	])("%p tokens weighs %p, by the bucket on its side of the boundary", (size, weight) => {
		expect(weighted([size])).toEqual([weight]);
	});

	test("keeps the order of the sizes", () => {
		expect(weighted([30000, 100, 2000, 1000, 10000])).toEqual([67500, 50, 2500, 1000, 15000]);
	});

	test("an empty list weighs nothing", () => {
		expect(weighted([])).toEqual([]);
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => weighted([100, -1])).toThrow(RangeError);
	});
});

