import { describe, expect, test } from "bun:test";

import { bucketOf, histogram, totalOf, turnSizes } from "./budget-table.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	test.each([
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
	] as const)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"rejects %p with a RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const preamble: HarnessMessage = { role: "assistant", content: "Ready when you are." };
	const firstPrompt: HarnessMessage = { role: "user", content: "Summarise the design doc." };
	const firstReply: HarnessMessage = {
		role: "assistant",
		content: "It splits the store into a journal and an index, rebuilt on start.",
	};
	const secondPrompt: HarnessMessage = { role: "user", content: "And the index format?" };
	const secondReply: HarnessMessage = { role: "assistant", content: "Line-delimited JSON." };

	test("sizes each prompted Turn and drops the messages before the first prompt", () => {
		const sizes = turnSizes([preamble, firstPrompt, firstReply, secondPrompt, secondReply]);

		expect(sizes).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("keeps a first Turn whose prompt text is empty", () => {
		const emptyPrompt: HarnessMessage = { role: "user", content: "" };

		expect(turnSizes([emptyPrompt, firstReply])).toEqual([
			approximateTokens([emptyPrompt, firstReply]),
		]);
	});
});

describe("histogram", () => {
	test("counts the sample from largest bucket to smallest", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("leaves out an empty huge but keeps the other empty buckets at zero", () => {
		expect(histogram([100, 7500])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("an empty list gives every bucket but huge at zero", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});
});

describe("totalOf", () => {
	test("sums the sizes, and is zero for none", () => {
		expect(totalOf([120, 90, 2400, 400, 8000])).toBe(11010);
		expect(totalOf([])).toBe(0);
	});
});

