 * from `reconstructTurns` as a leading Turn, but they answer no prompt, so that
 * Turn is dropped and its messages are not counted. It is recognised by its
 * first message not being the user's, not by its empty `prompt`: a user prompt
 * with empty text also has `prompt === ""` and is a real Turn.
 */
export function turnSizes(messages: HarnessMessage[]): number[] {
	const turns = reconstructTurns(messages);
	const prompted = turns[0]?.messages[0]?.role === "user" ? turns : turns.slice(1);
	return prompted.map((turn) => approximateTokens(turn.messages));
}

/**
 * How many sizes fall in each bucket, largest bucket first. Every bucket gets
 * an entry, count 0 if empty, except `huge`, which is left out when empty.
 * Throws RangeError for a size `bucketOf` rejects.
 */
export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) counts[bucketOf(size)] += 1;
	return [...BUCKETS]
		.reverse()
		.filter((bucket) => bucket !== "huge" || counts.huge > 0)
		.map((bucket) => ({ bucket, count: counts[bucket] }));
}

/** The plain, unweighted sum of the sizes; 0 for none. */
export function totalOf(sizes: number[]): number {
	return sizes.reduce((total, size) => total + size, 0);
}

/** How much a Turn's size counts against the Budget, by its bucket; see `notes/weights.md`. */
const WEIGHT: Record<Bucket, number> = {
	tiny: 0.5,
	small: 1,
	medium: 1.25,
	large: 1.5,
	huge: 2.25,
};

/**
 * A Turn's weighted size: its size times its bucket's weight, rounded to the
 * nearest multiple of 10 with halves up (`notes/rounding.md`).
 */
function weightOf(size: number, bucket: Bucket): number {
	return Math.round((size * WEIGHT[bucket]) / 10) * 10;
}

/**
 * Each size's weighted size, parallel to `sizes`.
 * Throws RangeError for a size `bucketOf` rejects.
 */
export function weighted(sizes: number[]): number[] {
	return sizes.map((size) => weightOf(size, bucketOf(size)));
}

/**
 * The sum of the weighted sizes in each bucket, every bucket present, 0 if
 * empty. Each Turn is rounded before summing, since the rounding rule applies
 * to a Turn's weighted size. Throws RangeError for a size `bucketOf` rejects.
 */
export function bucketTotals(sizes: number[]): Map<Bucket, number> {
	const totals: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) {
		const bucket = bucketOf(size);
		totals[bucket] += weightOf(size, bucket);
	}
	return new Map(BUCKETS.map((bucket) => [bucket, totals[bucket]]));
}

/**
 * A number as a rendered table shows it (`notes/rounding.md`): as is below
 * 1000, otherwise in thousands to one decimal, halves up, with a `k`.
 */
export function formatCount(n: number): string {
	if (n < 1000) return String(n);
	// Whole hundreds, rounded here rather than by `toFixed`, which rounds the
	// binary value and can take a decimal half down.
	const tenths = Math.round(n / 100);
	return `${Math.floor(tenths / 10)}.${tenths % 10}k`;
}

/** A bucket's row label in a rendered table; see `notes/legend.md`. */
const LABEL: Record<Bucket, string> = {
	tiny: "crumbs",
	small: "bites",
	medium: "meals",
	large: "feasts",
	huge: "banquets",
};

/** The row label a rendered table gives `bucket`. */
export function labelOf(bucket: Bucket): string {
	return LABEL[bucket];
}

