// owner: OWN-9314
import { bucketTotals, formatCount, histogram, labelOf } from "./budget-table.ts";

/**
 * The budget table as rows (`notes/legend.md`): a header, then one row per
 * histogram entry in histogram order, columns joined by ` | ` unpadded.
 * Throws RangeError for a size `bucketOf` rejects.
 */
export function renderTable(sizes: number[]): string[] {
	const totals = bucketTotals(sizes);
	const rows = histogram(sizes).map(({ bucket, count }) =>
		[labelOf(bucket), String(count), formatCount(totals.get(bucket) ?? 0)].join(" | "),
	);
	return ["bucket | turns | weighted", ...rows];
}

